+/**
+ * List of allowed attribute prefixes for hot spot elements.
+ * Event handler attributes (on*) and other dangerous attributes are excluded.
+ * @type {string[]}
+ */
+const ALLOWED_ATTRIBUTE_PREFIXES = [
+    'id',
+    'class',
+    'style',
+    'title',
+    'data-',
+    'aria-',
+    'role',
+    'tabindex',
+    'lang',
+    'dir'
+];
+
 /**
  * Checks if an attribute name is safe to set on an element.
  * @param {string} name - The attribute name to check.
  * @returns {boolean} True if the attribute is allowed.
  */
+function isAllowedAttribute(name) {
+    const lowerName = name.toLowerCase();
+    // Block event handler attributes (on*)
+    if (lowerName.startsWith('on')) {
+        return false;
+    }
+    // Block other dangerous attributes
+    const dangerousAttributes = ['href', 'src', 'action', 'formaction', 'xlink:href'];
+    if (dangerousAttributes.includes(lowerName)) {
+        return false;
+    }
+    // Allow if it matches an allowed prefix
+    return ALLOWED_ATTRIBUTE_PREFIXES.some(prefix => lowerName === prefix || lowerName.startsWith(prefix));
+}
+
+/**
  * Creates a hot spot element from configuration.
  * @param {Object} config - Hot spot configuration.
