-            element.setAttribute(key, value);
-        }
-    }
+    // Apply custom attributes from config, filtering for safety
+    if (config.attributes) {
+        for (const [key, value] of Object.entries(config.attributes)) {
+            if (isAllowedAttribute(key)) {
+                element.setAttribute(key, value);
+            } else {
+                console.warn(`Pannellum: Ignoring unsafe attribute "${key}" on hot spot.`);
+            }
+        }
+    }

     return element;
 }

