+/**
+ * Validates that a URL is a known Firebase Auth domain.
+ * Prevents attackers from injecting arbitrary _authTokenSyncURL via cookies.
+ */
+export function isValidFirebaseAuthDomain(url: string): boolean {
+  try {
+    const parsed = new URL(url);
+    
+    // Only allow HTTPS
+    if (parsed.protocol !== 'https:') {
+      return false;
+    }
+    
+    // Known Firebase Auth domains
+    const allowedHosts = [
+      'www.googleapis.com',
+      'identitytoolkit.googleapis.com',
+      'securetoken.googleapis.com',
+      'firebaseauth.googleapis.com'
+    ];
+    
+    // Also allow project-specific Firebase domains (e.g., <project>.firebaseapp.com)
+    const isFirebaseAppDomain = parsed.hostname.endsWith('.firebaseapp.com');
+    const isFirebaseAuthDomain = parsed.hostname.endsWith('.firebaseauth.com');
+    
+    return allowedHosts.includes(parsed.hostname) || 
+           isFirebaseAppDomain || 
+           isFirebaseAuthDomain;
+  } catch {
+    return false;
+  }
+}

