+++ b/src/utils/sanitize.js
@@ -0,0 +1,15 @@
+/**
+ * Strips HTML tags from a string to prevent XSS.
+ * @param {string} input - The input string that may contain HTML.
+ * @returns {string} The input with all HTML tags removed.
+ */
+export function stripHtmlTags(input) {
+  if (typeof input !== 'string') {
+    return input;
+  }
+  // Remove all HTML tags including self-closing tags
+  return input.replace(/<[^>]*>/g, '');
+}
+
+/**
+ * Recursively strips HTML tags from all string values in an object.
+ * @param {Object} obj - The object to sanitize.
+ * @returns {Object} A new object with HTML tags stripped from string values.
+ */
+export function stripHtmlTagsFromObject(obj) {
+  if (obj === null || typeof obj !== 'object') {
+    return obj;
+  }
+  
+  if (Array.isArray(obj)) {
+    return obj.map(item => stripHtmlTagsFromObject(item));
+  }
+  
+  const sanitized = {};
+  for (const [key, value] of Object.entries(obj)) {
+    if (typeof value === 'string') {
+      sanitized[key] = stripHtmlTags(value);
+    } else if (typeof value === 'object' && value !== null) {
+      sanitized[key] = stripHtmlTagsFromObject(value);
+    } else {
+      sanitized[key] = value;
+    }
+  }
+  return sanitized;
+}
