@@ -0,0 +1,58 @@
+import type { IncomingMessage } from 'http'
+
+/**
+ * Validates that an HTTP request has consistent, unambiguous framing
+ * to prevent request smuggling/desynchronization attacks.
+ * 
+ * Per RFC 7230 Section 3.3.3, a request with both Content-Length and
+ * Transfer-Encoding headers is ambiguous and should be rejected.
+ * Additionally, we validate header formatting to prevent parsing discrepancies.
+ */
+export function isValidHttpRequest(req: IncomingMessage): boolean {
+  const headers = req.headers
+
+  // Check for conflicting Content-Length and Transfer-Encoding headers
+  // This is the primary vector for HTTP request smuggling
+  const hasContentLength = 'content-length' in headers
+  const hasTransferEncoding = 'transfer-encoding' in headers
+
+  if (hasContentLength && hasTransferEncoding) {
+    return false
+  }
+
+  // Validate Content-Length: must be a single non-negative integer
+  if (hasContentLength) {
+    const contentLength = headers['content-length']
+    const values = Array.isArray(contentLength) ? contentLength : [contentLength]
+    
+    // Multiple Content-Length headers with different values = smuggling attempt
+    if (values.length > 1) {
+      const first = values[0]
+      if (values.some(v => v !== first)) {
+        return false
+      }
+    }
+
+    const clValue = values[0]
+    if (!/^\d+$/.test(clValue)) {
+      return false
+    }
+
+    // Reject negative or excessively large content lengths
+    const length = parseInt(clValue, 10)
+    if (length < 0 || length > 100 * 1024 * 1024) { // 100MB max
+      return false
+    }
+  }
+
+  // Validate Transfer-Encoding: only 'chunked' is supported, must be last
+  if (hasTransferEncoding) {
+    const transferEncoding = headers['transfer-encoding']
+    const values = Array.isArray(transferEncoding) ? transferEncoding : [transferEncoding]
+    
+    for (const te of values) {
+      const codings = te.toLowerCase().split(',').map(c => c.trim())
+      // Only 'chunked' is valid, and it must be the final coding
+      if (codings[codings.length - 1] !== 'chunked') {
+        return false
+      }
+      // Reject unknown or duplicate codings
+      const seen = new Set<string>()
+      for (const coding of codings) {
+        if (coding !== 'chunked' && coding !== 'identity') {
+          return false
+        }
+        if (seen.has(coding)) {
+          return false
+        }
+        seen.add(coding)
+      }
+    }
+  }
+
+  // Reject requests with obsolete line folding (RFC 7230 Section 3.2.4)
+  for (const [, value] of Object.entries(headers)) {
+    const values = Array.isArray(value) ? value : [value]
+    for (const v of values) {
+      if (/\r?\n[\t ]/.test(v)) {
+        return false
+      }
+    }
+  }
+
+  return true
+}
