+/**
+ * Python Sandbox for n8n Task Runners
+ * Provides secure Python code execution with strict isolation
+ */
+
+import { spawn, SpawnOptions } from 'child_process';
+import { writeFileSync, mkdtempSync, rmSync } from 'fs';
+import { join } from 'path';
+import { tmpdir } from 'os';
+import { randomBytes } from 'crypto';
+
+export interface SandboxConfig {
+	code: string;
+	inputData: IDataObject[];
+	timeout: number;
+	memoryLimit: number;
+	allowedModules: string[];
+	blockedBuiltins: string[];
+}
+
+export interface SandboxResult {
+	output?: INodeExecutionData[];
+	error?: string;
+	executionTime: number;
+}
+
+export interface ValidationResult {
+	safe: boolean;
+	reason?: string;
+	sanitizedCode?: string;
+}
+
+// Modules that are safe to import in the sandbox
+const SAFE_MODULES = new Set([
+	'json',
+	'math',
+	'random',
+	'datetime',
+	'decimal',
+	'fractions',
+	'statistics',
+	'itertools',
+	'functools',
+	'collections',
+	'string',
+	're',
+	'hashlib',
+	'hmac',
+	'base64',
+	'binascii',
+	'textwrap',
+	'unicodedata',
+	'html',
+	'urllib.parse',
+	'csv',
+	'xml.etree.ElementTree',
+	'dataclasses',
+	'typing',
+	'copy',
+	'pprint',
+	'enum',
+	'uuid',
+	'ipaddress',
+]);
+
+// Built-ins that must be blocked to prevent sandbox escape
+const DANGEROUS_BUILTINS = new Set([
+	'__import__',
+	'eval',
+	'exec',
+	'compile',
+	'open',
+	'input',
+	'breakpoint',
+	'help',
+	'license',
+	'copyright',
+	'credits',
+	'quit',
+	'exit',
+	'getattr',
+	'setattr',
+	'delattr',
+	'hasattr',
+	'vars',
+	'locals',
+	'globals',
+	'dir',
+	'__build_class__',
+]);
+
+// Dangerous patterns that indicate sandbox escape attempts
+const DANGEROUS_PATTERNS = [
+	/__import__\s*\(/,
+	/eval\s*\(/,
+	/exec\s*\(/,
+	/compile\s*\(/,
+	/open\s*\(/,
+	/os\./,
+	/subprocess\./,
+	/sys\./,
+	/builtins\./,
+	/__builtins__/,
+	/__globals__/,
+	/__locals__/,
+	/__class__/,
+	/__bases__/,
+	/__subclasses__/,
+	/__mro__/,
+	/ctypes/,
+	/multiprocessing/,
+	/threading/,
+	/socket/,
+	/urllib\.request/,
+	/http\./,
+	/ftplib/,
+	/telnetlib/,
+	/smtplib/,
+	/popen/,
+	/system\(/,
+	/spawn/,
+	/fork/,
+	/execve/,
+	/importlib/,
+	/pkgutil/,
+	/runpy/,
+	/zipimport/,
+	/imp\./,
+	/__loader__/,
+	/__spec__/,
+	/getattr\s*\(/,
+	/setattr\s*\(/,
+	/delattr\s*\(/,
+	/hasattr\s*\(/,
+	/vars\s*\(/,
+	/globals\s*\(/,
+	/locals\s*\(/,
+	/dir\s*\(/,
+];
+
+export class PythonSandbox {
+	private static instance: PythonSandbox;
+
+	private constructor() {}
+
+	public static getInstance(): PythonSandbox {
+		if (!PythonSandbox.instance) {
+			PythonSandbox.instance = new PythonSandbox();
+		}
+		return PythonSandbox.instance;
+	}
+
+	public getDefaultAllowedModules(): string[] {
+		return Array.from(SAFE_MODULES);
+	}
+
+	public getDefaultBlockedBuiltins(): string[] {
+		return Array.from(DANGEROUS_BUILTINS);
+	}
+
+	public validateCode(code: string): ValidationResult {
+		// Check for dangerous patterns
+		for (const pattern of DANGEROUS_PATTERNS) {
+			if (pattern.test(code)) {
+				return {
+					safe: false,
+					reason: `Dangerous pattern detected: ${pattern.source}`,
+				};
+			}
+		}
+
+		// Check for import statements
+		const importRegex = /^\s*(?:from\s+(\S+)\s+import|import\s+(\S+))/gm;
+		let match;
+		while ((match = importRegex.exec(code)) !== null) {
+			const moduleName = match[1] || match[2];
+			const baseModule = moduleName.split('.')[0];
+			if (!SAFE_MODULES.has(baseModule)) {
+				return {
+					safe: false,
+					reason: `Import of non-allowed module: ${baseModule}`,
+				};
+			}
+		}
+
+		// Check for attribute access on dangerous objects
+		const attrAccessRegex = /\b(__builtins__|__globals__|__locals__|__class__|__bases__|__subclasses__|__mro__)\b/;
+		if (attrAccessRegex.test(code)) {
+			return {
+				safe: false,
+				reason: 'Access to dangerous dunder attributes detected',
+			};
+		}
+
+		// Sanitize code by wrapping in safe execution context
+		const sanitizedCode = this.sanitizeCode(code);
+
+		return {
+			safe: true,
+			sanitizedCode,
+		};
+	}
+
+	private sanitizeCode(code: string): string {
+		// Wrap user code in a restricted execution environment
+		return `
+import sys
+import builtins
+import json
+
+# Remove dangerous builtins
+_blocked_builtins = ${JSON.stringify(Array.from(DANGEROUS_BUILTINS))}
+for name in _blocked_builtins:
+    if hasattr(builtins, name):
+        delattr(builtins, name)
+
+# Restrict sys module
+sys.modules = {k: v for k, v in sys.modules.items() if k in ${JSON.stringify(Array.from(SAFE_MODULES))} or k.startswith('_')}
+sys.path = [p for p in sys.path if not p.endswith('site-packages')]
+
+# Disable bytecode generation
+sys.dont_write_bytecode = True
+
+# User code starts here
+${code}
+
+# Ensure result is JSON serializable
+if 'result' in locals():
+    print(json.dumps(result, default=str))
+`;
+	}
+
+	public async execute(config: SandboxConfig): Promise<SandboxResult> {
+		const startTime = Date.now();
+		const tempDir = mkdtempSync(join(tmpdir(), 'n8n-python-'));
+		const scriptPath = join(tempDir, 'script.py');
+		const inputPath = join(tempDir, 'input.json');
+		const outputPath = join(tempDir, 'output.json');
+
+		try {
+			// Write sanitized code to file
+			writeFileSync(scriptPath, config.code, { mode: 0o600 });
+
+			// Write input data
+			writeFileSync(inputPath, JSON.stringify(config.inputData), { mode: 0o600 });
+
+			// Prepare restricted environment
+			const env: SpawnOptions['env'] = {
+				PATH: '/usr/bin:/bin',
+				PYTHONPATH: '',
+				PYTHONNOUSERSITE: '1',
+				PYTHONDONTWRITEBYTECODE: '1',
+				PYTHONUNBUFFERED: '1',
+				HOME: tempDir,
+				USER: 'nobody',
+			};
+
+			// Execute with strict resource limits
+			const result = await this.runWithLimits(
+				'python3',
+				[
+					'-I',  # Isolated mode
+					'-S',  # No site module
+					'-s',  # No user site
+					'-B',  # No bytecode
+					'-c',
+					`
+import sys
+import json
+import resource
+
+# Set resource limits
+resource.setrlimit(resource.RLIMIT_CPU, (${Math.ceil(config.timeout / 1000)}, ${Math.ceil(config.timeout / 1000)}))
+resource.setrlimit(resource.RLIMIT_AS, (${config.memoryLimit}, ${config.memoryLimit}))
+resource.setrlimit(resource.RLIMIT_FSIZE, (1024 * 1024, 1024 * 1024))  # 1MB max file size
+resource.setrlimit(resource.RLIMIT_NOFILE, (10, 10))
+resource.setrlimit(resource.RLIMIT_NPROC, (1, 1))
+
+# Load user script
+with open('${scriptPath.replace(/\\/g, '\\\\')}') as f:
+    code = f.read()
+
+# Load input data
+with open('${inputPath.replace(/\\/g, '\\\\')}') as f:
+    items = json.load(f)
+
+# Execute in restricted namespace
+namespace = {'items': items, '__builtins__': {k: v for k, v in __builtins__.items() if k not in ${JSON.stringify(config.blockedBuiltins)}}}
+exec(code, namespace)
+
+# Write output
+result = namespace.get('result', namespace.get('output', items))
+with open('${outputPath.replace(/\\/g, '\\\\')}', 'w') as f:
+    json.dump(result, f, default=str)
+`,
+				],
+				{
+					cwd: tempDir,
+					env,
+					timeout: config.timeout,
+					stdio: ['ignore', 'pipe', 'pipe'],
+				},
+			);
+
+			if (result.exitCode !== 0) {
+				return {
+					error: result.stderr || `Process exited with code ${result.exitCode}`,
+					executionTime: Date.now() - startTime,
+				};
+			}
+
+			// Read output
+			let output: INodeExecutionData[] = [];
+			try {
+				const outputContent = require('fs').readFileSync(outputPath, 'utf-8');
+				output = JSON.parse(outputContent);
+				if (!Array.isArray(output)) {
+					output = [output];
+				}
+			} catch (e) {
+				return {
+					error: 'Failed to parse output',
+					executionTime: Date.now() - startTime,
+				};
+			}
+
+			return {
+				output,
+				executionTime: Date.now() - startTime,
+			};
+		} finally {
+			// Cleanup
+			try {
+				rmSync(tempDir, { recursive: true, force: true });
+			} catch {
+				// Ignore cleanup errors
+			}
+		}
+	}
+
+	private runWithLimits(
+		command: string,
+		args: string[],
+		options: SpawnOptions,
+	): Promise<{ exitCode: number; stdout: string; stderr: string }> {
+		return new Promise((resolve) => {
+			const child = spawn(command, args, options);
+			let stdout = '';
+			let stderr = '';
+
+			child.stdout?.on('data', (data) => {
+				stdout += data.toString();
+			});
+
+			child.stderr?.on('data', (data) => {
+				stderr += data.toString();
+			});
+
+			child.on('close', (code) => {
+				resolve({ exitCode: code ?? 1, stdout, stderr });
+			});
+
+			child.on('error', (err) => {
+				resolve({ exitCode: 1, stdout, stderr: err.message });
+			});
+		});
+	}
+}
+
+// Export singleton instance
+export const pythonSandbox = PythonSandbox.getInstance();
