+import { pythonSandbox } from '../index';
+
+describe('PythonSandbox', () => {
+	describe('validateCode', () => {
+		it('should allow safe code', () => {
+			const result = pythonSandbox.validateCode(`
+				import json
+				result = [{"processed": item.get("value", "")} for item in items]
+			`);
+			expect(result.safe).toBe(true);
+			expect(result.sanitizedCode).toBeDefined();
+		});
+
+		it('should block os module import', () => {
+			const result = pythonSandbox.validateCode('import os\nresult = os.listdir(".")');
+			expect(result.safe).toBe(false);
+			expect(result.reason).toContain('non-allowed module');
+		});
+
+		it('should block subprocess module import', () => {
+			const result = pythonSandbox.validateCode('import subprocess\nresult = subprocess.run(["ls"])');
+			expect(result.safe).toBe(false);
+		});
+
+		it('should block sys module access', () => {
+			const result = pythonSandbox.validateCode('import sys\nresult = sys.modules');
+			expect(result.safe).toBe(false);
+		});
+
+		it('should block __import__ usage', () => {
+			const result = pythonSandbox.validateCode('__import__("os")');
+			expect(result.safe).toBe(false);
+		});
+
+		it('should block eval usage', () => {
+			const result = pythonSandbox.validateCode('eval("1+1")');
+			expect(result.safe).toBe(false);
+		});
+
+		it('should block exec usage', () => {
+			const result = pythonSandbox.validateCode('exec("import os")');
+			expect(result.safe).toBe(false);
+		});
+
+		it('should block open usage', () => {
+			const result = pythonSandbox.validateCode('open("/etc/passwd").read()');
+			expect(result.safe).toBe(false);
+		});
+
+		it('should block __builtins__ access', () => {
+			const result = pythonSandbox.validateCode('result = __builtins__');
+			expect(result.safe).toBe(false);
