+name: Python Sandbox Security Tests
+
+on:
+  push:
+    branches: [main, develop]
+  pull_request:
+    branches: [main, develop]
+
+jobs:
+  python-sandbox-tests:
+    runs-on: ubuntu-latest
+    steps:
+      - uses: actions/checkout@v4
+
+      - name: Setup Node.js
+        uses: actions/setup-node@v4
+        with:
+          node-version: '20'
+          cache: 'npm'
+
+      - name: Install dependencies
+        run: npm ci
+
+      - name: Run Python sandbox unit tests
+        run: npm test -- --testPathPattern="python-sandbox"
+
+      - name: Run sandbox escape attempt tests
+        run: |
+          cat > /tmp/escape_attempts.py << 'EOF'
+          # Test cases that should be blocked
+          escape_attempts = [
+              'import os; os.system("id")',
+              'import subprocess; subprocess.run(["id"])',
+              '__import__("os").system("id")',
+              'eval("__import__(\\"os\\").system(\\"id\\")")',
+              'exec("import os; os.system(\\"id\\")")',
+              'open("/etc/passwd").read()',
+              '().class.__bases__[0].__subclasses__()',
+              '__builtins__.__import__("os")',
+              'getattr(__builtins__, "__import__")("os")',
+              'import ctypes; ctypes.CDLL("libc.so.6")',
+              'import sys; sys.modules["os"]',
+              'import importlib; importlib.import_module("os")',
+          ]
+
+          for attempt in escape_attempts:
+              print(f"Testing: {attempt[:50]}...")
+              # These should all be caught by validation
+          EOF
+          python3 /tmp/escape_attempts.py
+
+      - name: Integration test with Task Runner
+        if: ${{ env.N8N_RUNNERS_ENABLED == 'true' }}
+        run: |
+          # Start n8n with runners enabled
+          N8N_RUNNERS_ENABLED=true N8N_PYTHON_ENABLED=true npm run start:dev &
+          sleep 10
+          # Run integration tests
+          npm run test:integration:python
+          kill %1

