+    .replace(/`/g, '\\`')
+    .replace(/\$/g, '\\$')
+    .replace(/\${/g, '\\${')
+    .replace(/\r/g, '\\r')
+    .replace(/\n/g, '\\n')
+    .replace(/\t/g, '\\t')
+    .replace(/\f/g, '\\f')
+    .replace(/\v/g, '\\v');
+};
