+export function isValidModuleSpecifier(specifier) {
+  if (typeof specifier !== 'string' || specifier.length === 0) {
+    return false;
+  }
+
+  // Reject specifiers with null bytes or control characters
+  if (/[\x00-\x1F\x7F]/.test(specifier)) {
+    return false;
+  }
+
+  // Reject specifiers that look like data: or javascript: URLs
